package com.mavric.health.persistence.sqlserver;
import java.util.*;
import java.sql.SQLException;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import org.springframework.security.core.context.SecurityContextHolder;
import com.mavric.health.audit.TraceContext;
import com.mavric.health.identity.Actor;
import com.mavric.health.tenancy.TenantRef;
import com.mavric.health.shared.ApiException;
import com.mavric.health.persistence.sqlserver.SqlServerIdentityStoreTest.ModelTransactionManager;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Real templates and modeled executor/manager: no JDBC or durable independent transaction. */
class SqlServerTraceStoreTest {
 static final String ID="aa000000-0000-4000-8000-000000000001",TENANT="bb000000-0000-4000-8000-000000000001",HASH="a".repeat(64);
 final SqlServerExecutor executor=mock(SqlServerExecutor.class);final ModelTransactionManager manager=new ModelTransactionManager();final SqlServerTraceStore store=new SqlServerTraceStore(executor,manager);
 final MockHttpServletRequest request=new MockHttpServletRequest("POST","/api/trace");
 final List<SqlServerContext> contexts=new ArrayList<>();final List<List<Object>> args=new ArrayList<>();
 SqlServerTraceStoreTest(){request.setAttribute("health.requestId",ID);when(executor.execute(any(),any(),any(Object[].class))).thenAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());assertEquals(SqlServerProcedure.REQUEST_FINISH,inv.getArgument(0));contexts.add(inv.getArgument(1));args.add(Arrays.asList(((Object[])inv.getRawArguments()[2]).clone()));return new SqlServerExecutor.Result(List.of(),List.of(0));});}
 @AfterEach void cleanup(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
 @Test void exactDescriptorBoundaryMetricsAndRequiresNew(){store.finish(request,ID,100,0);store.finish(request,ID,599,Long.MAX_VALUE);assertEquals(List.of(100,0L),args.getFirst());assertEquals(List.of(599,Long.MAX_VALUE),args.getLast());assertEquals(List.of("begin:3","commit","begin:3","commit"),manager.events);assertEquals(SqlServerContext.Scope.REQUEST,contexts.getFirst().scope());assertEquals(ID,contexts.getFirst().requestId());}
 @Test void usesFinalAttributesNotThreadLocalHeadersOrSecurityContextAndTruncatesUnicode(){request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of()));request.setAttribute("health.actor",new Actor(ID,"Synthetic","qa@example.test",TENANT,List.of("ADM"),HASH));request.setRequestURI("/"+"x".repeat(248)+"\ud83e\uddb7");request.addHeader("User-Agent","a".repeat(299)+"\ud83e\uddb7");request.setRemoteAddr("127.0.0.9");request.addHeader("X-Forwarded-For","forged");request.addHeader("Cookie","canary");request.addHeader("Authorization","canary");request.setQueryString("secret=canary");TraceContext.REQUEST.set(new MockHttpServletRequest("DELETE","/wrong"));store.finish(request,ID,201,4);var c=contexts.getFirst();assertEquals(ID,c.actorId());assertEquals(TENANT,c.tenantId());assertEquals(HASH,c.tokenHash());assertEquals(249,c.route().length());assertEquals(299,c.userAgent().length());assertEquals("127.0.0.9",c.sourceIp());assertEquals("POST",c.method());assertFalse(c.route().contains("canary"));}
 @Test void suspendsAndResumesOuterThenOuterRollbackDoesNotUndoModeledTraceCommit(){assertThrows(RuntimeException.class,()->manager.outer(()->{store.finish(request,ID,500,10);assertEquals(List.of("begin:0","suspend","begin:3","commit","resume"),manager.events);throw new RuntimeException("synthetic outer rollback");}));assertEquals("rollback",manager.events.getLast());assertEquals(1,args.size());}
 @Test void malformedCorrelationAndMetricsNeverExecutor(){for(String id:Arrays.asList(null,"bad",ID.toUpperCase(Locale.ROOT))){assertEquals(500,assertThrows(ApiException.class,()->store.finish(request,id,200,0)).status);}assertEquals(500,assertThrows(ApiException.class,()->store.finish(null,ID,200,0)).status);request.setAttribute("health.requestId",1);assertEquals(500,assertThrows(ApiException.class,()->store.finish(request,ID,200,0)).status);request.setAttribute("health.requestId",ID);for(int status:new int[]{99,600})assertEquals(400,assertThrows(ApiException.class,()->store.finish(request,ID,status,0)).status);assertEquals(400,assertThrows(ApiException.class,()->store.finish(request,ID,200,-1)).status);verifyNoInteractions(executor);}
 @Test void malformedInternalActorTenantAndHashFail500WithoutAnonymizing(){for(int mode=0;mode<5;mode++){request.removeAttribute("health.actor");request.removeAttribute("health.tenant");switch(mode){case 0->request.setAttribute("health.tenant","forged");case 1->request.setAttribute("health.tenant",new TenantRef("bad","x","x","CLINIC","HUMAN","ACTIVE",List.of()));case 2->request.setAttribute("health.actor",new Actor("bad","x","qa@example.test",null,List.of("SAD"),HASH));case 3->request.setAttribute("health.actor",new Actor(ID,"x","qa@example.test",null,List.of("SAD"),"bad"));case 4->request.setAttribute("health.actor",new Actor(ID,"x","qa@example.test",TENANT,List.of("ADM"),HASH));}assertEquals(500,assertThrows(ApiException.class,()->store.finish(request,ID,200,0)).status);}verifyNoInteractions(executor);}
 @Test void unexpectedRsDriverAndCommitFailuresSafeNoRetry(){when(executor.execute(any(),any(),any(Object[].class))).thenReturn(new SqlServerExecutor.Result(List.of(List.of()),List.of()));safe(()->store.finish(request,ID,200,0));doThrow(new RuntimeException(new SQLException("canary driver",null,229))).when(executor).execute(any(),any(),any(Object[].class));safe(()->store.finish(request,ID,200,0));doReturn(new SqlServerExecutor.Result(List.of(),List.of())).when(executor).execute(any(),any(),any(Object[].class));manager.failCommit=true;safe(()->store.finish(request,ID,200,0));verify(executor,times(3)).execute(any(),any(),any(Object[].class));}
 static void safe(Runnable work){var e=assertThrows(ApiException.class,work::run);assertEquals(500,e.status);assertEquals("DATABASE_ERROR",e.code);assertNull(e.getCause());assertFalse(e.toString().contains("canary"));}
 @Test void platformActorAndVendorErrorsKeepTheirSafeMeaning(){request.setAttribute("health.actor",new Actor(ID,"Synthetic","qa@example.test",null,List.of("SAD"),HASH));store.finish(request,ID,200,1);assertEquals(ID,contexts.getFirst().actorId());assertNull(contexts.getFirst().tenantId());for(int code:new int[]{51000,51001,51002,51003}){doThrow(new RuntimeException(new SQLException("canary vendor",null,code))).when(executor).execute(any(),any(),any(Object[].class));var error=assertThrows(ApiException.class,()->store.finish(request,ID,500,2));assertEquals(code==51000?400:code==51001?403:code==51002?404:409,error.status);assertFalse(error.toString().contains("canary"));assertEquals("rollback",manager.events.getLast());}verify(executor,times(5)).execute(any(),any(),any(Object[].class));}

}
